 harbor:{title:['Aduana de lo ausente','Customs of the absent'],npc:'celso',npcX:638,npcH:188,foot:646,ambient:[.47,.52,.66],lights:[{p:[234,370,85],c:[3.4,1.5,.48],r:630},{p:[1240,165,165],c:[.4,1.25,2.8],r:1140},{p:[715,625,160],c:[.55,.3,.16],r:710}]},
