function frame(now){
 requestAnimationFrame(frame);if(!renderer||renderer.lost||document.hidden)return;const dt=Math.min(.2,(now-lastTime)/1000||.016);lastTime=now;
 const delta=tx-state.x;moving=playing&&Math.abs(delta)>1.5&&$('overlay').hidden&&$('dialogue').hidden;
 if(moving){const step=Math.sign(delta)*Math.min(Math.abs(delta),205*dt);state.x+=step;state.face=step>=0?1:-1;walkPhase+=Math.abs(step)/42*Math.PI*2;}else if(Math.abs(delta)<=1.5){state.x=tx;if(pending){const action=pending;pending=null;action();save();}}
 const scene=SCENES[state.scene],lamp=state.lamp,colors=[[2.75,2.55,2.1],[3.6,1.45,.2],[.25,2.55,3.65]],lights=[...scene.lights.map(l=>({...l,p:[...l.p],c:[...l.c]})),{p:[lamp.x,lamp.y,lamp.z],c:colors[lamp.color],r:820}];
 if(!reduced)lights[0].c=lights[0].c.map(c=>c*(1+.023*Math.sin(now*.0031)+.015*Math.sin(now*.0074)));
 if(state.scene==='lighthouse'&&state.flags.beams){lights[0].c=[2.3,.4,.3];lights[1].c=[.25,1.4,3.2];lights[2].c=[.5,2.2,1.1];}
 renderer.begin(lights,scene.ambient,state.exposure);renderer.draw(state.scene,[0,0,W,H],{spec:.18});
 const npc=npcObject();if(npc){renderer.draw('contact',[scene.npcX-65,scene.foot-9,130,19],{shadow:true,opacity:.65});renderer.draw(npc.id,npc.r,{spec:.045,gain:.54});}
 const r=boundsFor(cat.name,state.x,cat.foot,cat.height);const phase=reduced?0:moving?walkPhase:now*.001;
 renderer.draw('contact',[state.x-62,cat.foot-8,124,15],{shadow:true,opacity:.4});
 renderer.draw(cat.name,r,{cat:true,flip:state.face,phase,walk:moving?1:0,spec:.02,gain:.40});renderer.end();
 effects(now,lights);modalTick?.(now);
}
function effects(now,lights){const c=$('effects').getContext('2d');c.clearRect(0,0,W,H);if(renderer.normalView)return;
 // Subtle atmosphere is a separate overlay; material relighting is in WebGL.
 if(!reduced){c.globalCompositeOperation='screen';for(let i=0;i<32;i++){const x=(i*179+Math.sin(now*.00023+i)*15)%W,y=100+(i*67+now*.008)%470;const light=lights[3],dist=Math.hypot(x-light.p[0],y-light.p[1]),alpha=Math.max(0,1-dist/440)*.35;c.fillStyle='rgba(236,211,166,'+alpha+')';c.beginPath();c.arc(x,y,.7+(i%3)*.35,0,Math.PI*2);c.fill();}c.globalCompositeOperation='source-over';}
 if(state.lamp.pinned){c.strokeStyle='#e6cc9699';c.lineWidth=1;c.beginPath();c.arc(state.lamp.x,state.lamp.y,9,0,Math.PI*2);c.moveTo(state.lamp.x-13,state.lamp.y);c.lineTo(state.lamp.x+13,state.lamp.y);c.moveTo(state.lamp.x,state.lamp.y-13);c.lineTo(state.lamp.x,state.lamp.y+13);c.stroke();}
}
const game={t,$,get state(){return state;},has,add,remove,flag,remember,note,save,modal,closeModal,say,button,ui,go,finish,setTick(fn){modalTick=fn;},get renderer(){return renderer;}};
async function boot(){try{
 renderer=new Renderer($('world'));await renderer.load(['harbor','tavern','archive','lighthouse','cat-look','cat-idle','cat-walk','cat-sit','celso','lua','ofelia'],v=>$('progress').value=v);
 for(const [name,im] of Object.entries(renderer.images)){if(SCENES[name])continue;const c=document.createElement('canvas');c.width=im.width;c.height=im.height;const ctx=c.getContext('2d',{willReadFrequently:true});ctx.drawImage(im,0,0);const data=ctx.getImageData(0,0,c.width,c.height).data;let x0=im.width,y0=im.height,x1=0,y1=0;for(let y=0;y<im.height;y++)for(let x=0;x<im.width;x++)if(data[(y*im.width+x)*4+3]>40){x0=Math.min(x0,x);y0=Math.min(y0,y);x1=Math.max(x1,x);y1=Math.max(y1,y);}spriteInfo[name]={width:im.width,height:im.height,bw:x1-x0+1,bh:y1-y0+1,left:x0/im.width,top:y0/im.height,bottom:(y1+1)/im.height,alpha:data};}
 const shadow=document.createElement('canvas');shadow.width=128;shadow.height=40;const shade=shadow.getContext('2d'),gradient=shade.createRadialGradient(64,20,2,64,20,60);gradient.addColorStop(0,'#00000077');gradient.addColorStop(1,'#00000000');shade.fillStyle=gradient;shade.fillRect(0,0,128,40);const flat=document.createElement('canvas');flat.width=flat.height=2;const flatctx=flat.getContext('2d');flatctx.fillStyle='rgb(128,128,255)';flatctx.fillRect(0,0,2,2);renderer.add('contact',shadow,flat);
 puzzles=initPuzzles(game);wire();ui();$('loading').hidden=true;playing=true;requestAnimationFrame(frame);intro();
 // Read-only diagnostics used by the browser regression suite, not progression cheats.
 window.Bruma=Object.freeze({version:VERSION,get state(){return JSON.parse(JSON.stringify(state));},get moving(){return moving;},get busy(){return pending!==null||Math.abs(tx-state.x)>1.5;},get ready(){return true;},objects:()=>allObjects().map(({id,poly,mark,r})=>({id,poly,mark,r})),hit:(x,y)=>hit(x,y)?.id||null,worldToClient:(x,y)=>{const r=$('scene').getBoundingClientRect();return {x:r.left+x/W*r.width,y:r.top+y/H*r.height};},get rendererError(){return renderer.gl.getError();},get normalView(){return renderer.normalView;}});
 }catch(e){console.error(e);$('load-status').textContent=t('No se ha podido iniciar: ','Could not start: ')+e.message;$('loading').append(button(t('Reintentar','Retry'),()=>location.reload()));}}
